LABELS={'original':'Original · both-direction RSI','benchmark':'Pre-filter benchmark · short RSI','recovery':'Improved · recovery filter'}


def fmt(value,kind='number'):
    if value is None:return 'N/A'
    if kind=='money':return money(value)
    if kind=='signed':return money(value,True)
    if kind=='pct':return f'{value:.2f}%'
    if kind=='integer':return str(int(value))
    return f'{value:.2f}'


def table(headers,rows):
    cell=lambda x:'<td'+(' class="positive"' if str(x).startswith('+$') else ' class="negative"' if str(x).startswith('-$') else '')+'>'+str(x)+'</td>'
    return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+str(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(cell(x) for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'


